glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
layout(std140) uniform ALPHA_TEST_DATA {
  float alphaThreshold;
};
#endif
layout(std140) uniform HotParams {
  vec4 hotEdgeColor;
  vec4 hotYellowColor;
  vec4 hotMidColor;
  vec4 hotInnerColor;
  vec4 hotBaseTint;
  vec4 hotUvToDf;
  float hotStrength;
  float hotEdgeWidth;
  float hotBandRatio;
  float hotFadeStart;
  float hotFadeEnd;
  float hotEdgeBrightness;
  float hotResidual;
  float hotOverlay;
  float flashAmount;
};
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
#if USE_TEXTURE
uniform sampler2D cc_spriteTexture;
#endif
uniform sampler2D hotField;
float fieldDistance (vec2 uv) {
  vec2 fuv = uv * hotUvToDf.xy + hotUvToDf.zw;
  if (fuv.x < 0.0 || fuv.x > 1.0 || fuv.y < 0.0 || fuv.y > 1.0) return -1.0;
  return 1.0 - texture(hotField, fuv).a;
}
vec3 getHeatColor (float dist) {
  float edgeW = max(hotEdgeWidth, 0.0001);
  float band = max(hotBandRatio, 0.0001);
  vec3 brightEdge = min(hotEdgeColor.rgb * max(hotEdgeBrightness, 1.0), vec3(1.0));
  float toYellow = smoothstep(0.0, edgeW, dist);
  float toMid = smoothstep(edgeW, edgeW + band * 0.45, dist);
  float toInner = smoothstep(edgeW + band * 0.45, edgeW + band, dist);
  vec3 c = mix(brightEdge, hotYellowColor.rgb, toYellow);
  c = mix(c, hotMidColor.rgb, toMid);
  return mix(c, hotInnerColor.rgb, toInner);
}
float heatCoverage (float dist) {
  float start = max(hotFadeStart, 0.0);
  float end = max(hotFadeEnd, start + 0.0001);
  return mix(max(hotResidual, 0.0), 1.0, 1.0 - smoothstep(start, end, dist));
}
vec3 hotAdd (vec3 base, vec3 add) {
  vec3 s = base + max(add, vec3(0.0));
  float m = max(max(s.r, s.g), s.b);
  return m > 1.0 ? s / m : s;
}
vec4 frag () {
  vec4 o = vec4(1.0);
  #if USE_TEXTURE
    o *= CCSampleWithAlphaSeparated(cc_spriteTexture, uv0);
    #if IS_GRAY
      float gray = dot(o.rgb, vec3(0.2126, 0.7152, 0.0722));
      o.rgb = vec3(gray);
    #endif
  #endif
  o *= color;
  float strength = clamp(hotStrength, 0.0, 1.0);
  vec3 cold = o.rgb;
  vec3 hot = hotAdd(cold, hotBaseTint.rgb);
  if (o.a >= 0.5 && strength > 0.001) {
    float dist = fieldDistance(uv0);
    if (dist >= 0.0) {
      vec3 heat = getHeatColor(dist);
      float cov = clamp(heatCoverage(dist), 0.0, 1.0);
      hot = mix(hot, heat, cov);
      hot = hotAdd(hot, heat * cov * clamp(hotOverlay, 0.0, 1.0));
    }
  }
  o.rgb = mix(cold, hot, strength);
  o.rgb = mix(o.rgb, vec3(1.0), clamp(flashAmount, 0.0, 1.0));
  ALPHA_TEST(o);
  return o;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

